    render_institutional_lifecycle_panel()
    
    
    # Helper: wave scope extraction (used by multiple sections)
    def _extract_wave_scope(decision_text, known_wave_names):
        text_lower = decision_text.lower()
        for wn in known_wave_names:
            if wn.lower() in text_lower:
                return wn
        keyword_map = {
            "wave-eq": "Equity", "wave-mom": "Momentum", "wave-div": "Dividend",
            "wave-grow": "Growth", "wave-qual": "Quality", "gold": "Gold Wave",
            "income": "Core Institutional Income Wave", "crypto": "Crypto", "treasury": "Treasury",
            "muni": "Muni", "small cap": "Small Cap", "megacap": "MegaCap",
            "s&p": "S&P 500 Wave",
        }
        for kw, label in keyword_map.items():
            if kw in text_lower:
                for wn in known_wave_names:
                    if label.lower() in wn.lower():
                        return wn
                return "Portfolio (All Waves)"
        return "Portfolio (All Waves)"

    known_wave_names = []
    if snapshot_df is not None and not snapshot_df.empty and "wave_name" in snapshot_df.columns:
        known_wave_names = snapshot_df["wave_name"].dropna().unique().tolist()

    def build_enterprise_heatmap(snapshot_df, attrib_df, known_waves):
        import json as json_mod
        try:
            with open("data/decision_log.json", "r") as f:
                decisions = json_mod.load(f)
        except Exception:
            return []

        active_raw_statuses = ("Pending", "Monitoring", "Under Review", "Resolved")

        area_decisions = {}
        for d in decisions:
            raw_status = d.get("status", "")
            if raw_status not in active_raw_statuses:
                continue

            outcome_30d = d.get("outcome_30d", "Pending")
            outcome_90d = d.get("outcome_90d", "Pending")
            has_outcome = outcome_30d not in ("Pending", "N/A", "", None) or outcome_90d not in ("Pending", "N/A", "", None)

            if raw_status == "Pending":
                classified = "Awaiting Approval"
            elif raw_status == "Monitoring":
                classified = "Under Review"
            elif raw_status == "Resolved" and has_outcome:
                classified = "Outcome Ready"
            else:
                classified = "Under Review"

            decision_text = d.get("decision", "")
            wave_scope = _extract_wave_scope(decision_text, known_waves)

            if wave_scope not in area_decisions:
                area_decisions[wave_scope] = {"active": 0, "contexts": []}

            if classified in ("Awaiting Approval", "Under Review"):
                area_decisions[wave_scope]["active"] += 1

            regime_ctx = d.get("regime_context", d.get("context", ""))
            if regime_ctx:
                area_decisions[wave_scope]["contexts"].append(regime_ctx)

        vol_stress_level = None
        vol_regime_state = None
        try:
            tm = load_ticker_metrics()
            vv = [m["vol_30d"] for m in tm.values() if m.get("vol_30d") is not None]
            if vv and len(vv) >= 3:
                avg_v = np.mean(vv)
                if avg_v > 0.35:
                    vol_stress_level = "Elevated"
                elif avg_v > 0.22:
                    vol_stress_level = "Moderate"
                else:
                    vol_stress_level = "Low"

                vol_regime_state = "Insufficient Data"
                try:
                    prices_path = Path("data/prices.csv")
                    if prices_path.exists():
                        ppdf = pd.read_csv(prices_path, parse_dates=["date"])
                        ppdf = ppdf.sort_values("date")
                        adates = ppdf["date"].dropna().unique()
                        if len(adates) > 60:
                            r_start = adates[-30]
                            p_start = adates[-60]
                            r_data = ppdf[ppdf["date"] >= r_start]
                            p_data = ppdf[(ppdf["date"] >= p_start) & (ppdf["date"] < r_start)]
                            r_rets = r_data.groupby("ticker")["close"].apply(
                                lambda x: np.log(x / x.shift(1)).std() * np.sqrt(252) if len(x) > 5 else np.nan
                            ).dropna()
                            p_rets = p_data.groupby("ticker")["close"].apply(
                                lambda x: np.log(x / x.shift(1)).std() * np.sqrt(252) if len(x) > 5 else np.nan
                            ).dropna()
                            if len(r_rets) > 3 and len(p_rets) > 3:
                                r_avg = r_rets.mean()
                                p_avg = p_rets.mean()
                                if p_avg > 0:
                                    vcr = r_avg / p_avg
                                    vol_low = avg_v < 0.22
                                    vol_high = avg_v > 0.30
                                    vol_mid = not vol_low and not vol_high
                                    v_rising = vcr > 1.10
                                    v_falling = vcr < 0.90
                                    v_stable = not v_rising and not v_falling
                                    if vol_low and v_stable:
                                        vol_regime_state = "Compression"
                                    elif vol_low and v_rising:
                                        vol_regime_state = "Transition"
                                    elif vol_mid and v_rising:
                                        vol_regime_state = "Early Expansion"
                                    elif vol_high and v_rising:
                                        vol_regime_state = "Expansion"
                                    elif vol_high and v_falling:
                                        vol_regime_state = "Exhaustion"
                                    elif (vol_mid or vol_high) and v_falling:
                                        vol_regime_state = "Stabilizing"
                                    elif vol_mid and v_stable:
                                        vol_regime_state = "Compression"
                                    elif vol_low and v_falling:
                                        vol_regime_state = "Compression"
                                    else:
                                        vol_regime_state = "Transition"
                except Exception:
                    pass
        except Exception:
            pass

        has_review_signals = False
        if attrib_df is not None and not attrib_df.empty and "horizon" in attrib_df.columns:
            component_cols = ["selection_alpha", "momentum_alpha", "volatility_alpha", "regime_alpha", "exposure_alpha"]
            for col in component_cols:
                if col in attrib_df.columns:
                    neg_horizon_count = 0
                    for h in attrib_df["horizon"].dropna().unique():
                        h_data = attrib_df[attrib_df["horizon"] == h]
                        vals = pd.to_numeric(h_data[col], errors="coerce").dropna()
                        if len(vals) > 0 and vals.mean() < -0.005:
                            neg_horizon_count += 1
                    if neg_horizon_count >= 2:
                        has_review_signals = True
                        break

        rows = []
        for area, info in sorted(area_decisions.items()):
            active_count = info["active"]
            contexts = info["contexts"]

            elevated_ctx = sum(1 for c in contexts if c and any(kw in c.lower() for kw in ("elevated", "risk-off", "stress")))
            neutral_ctx = sum(1 for c in contexts if c and any(kw in c.lower() for kw in ("neutral", "stable", "trending")))

            vol_elevated = vol_stress_level in ("Elevated",) if vol_stress_level else False
            vol_moderate = vol_stress_level in ("Moderate",) if vol_stress_level else False
            regime_expanding = vol_regime_state in ("Expansion", "Early Expansion") if vol_regime_state else False

            if (elevated_ctx > 0 or vol_elevated or regime_expanding) and has_review_signals:
                dominant_context = "Review Recommended"
            elif elevated_ctx > 0 or vol_elevated or regime_expanding or has_review_signals:
                dominant_context = "Monitoring"
            elif vol_moderate:
                dominant_context = "Monitoring"
            elif neutral_ctx > 0 or vol_stress_level == "Low":
                dominant_context = "Stable"
            elif contexts:
                dominant_context = "Mixed"
            else:
                dominant_context = "Insufficient Data"

            if dominant_context == "Review Recommended":
                area_status = "Review Recommended"
            elif dominant_context in ("Monitoring", "Mixed"):
                area_status = "Monitoring"
            else:
                area_status = "Stable"

            rows.append({
                "Area": area,
                "Active Decisions": str(active_count),
                "Dominant Context": dominant_context,
                "Status": area_status,
            })

        if not rows:
            rows.append({
                "Area": "Portfolio (All Waves)",
                "Active Decisions": "0",
                "Dominant Context": "Insufficient Data",
                "Status": "Stable",
            })

        return rows
    
    def build_decision_latency(today_date):
        import json as json_mod
        try:
            with open("data/decision_log.json", "r") as f:
                decisions = json_mod.load(f)
        except Exception:
            return None, []

        latency_rows = []
        resolved_latencies = []
        active_latencies = []
        total_tracked = 0

        for d in decisions:
            dec_id = d.get("id", "")
            raw_status = d.get("status", "")
            dec_date_str = d.get("date", "")

            if raw_status == "Recorded":
                continue

            try:
                dec_date = pd.to_datetime(dec_date_str).date()
            except Exception:
                continue

            total_tracked += 1
            outcome_30d = d.get("outcome_30d", "Pending")
            outcome_90d = d.get("outcome_90d", "Pending")
            has_outcome = outcome_30d not in ("Pending", "N/A", "", None) or outcome_90d not in ("Pending", "N/A", "", None)

            if raw_status == "Resolved" and has_outcome:
                if outcome_30d not in ("Pending", "N/A", "", None):
                    obs_days = 30
                elif outcome_90d not in ("Pending", "N/A", "", None):
                    obs_days = 90
                else:
                    obs_days = (today_date - dec_date).days
                resolved_latencies.append(obs_days)
                latency_label = f"{obs_days}d (Observed)"
                phase = "Outcome Recorded"
            elif raw_status in ("Pending",):
                elapsed = (today_date - dec_date).days
                active_latencies.append(elapsed)
                latency_label = f"{elapsed}d (Active)"
                phase = "Awaiting Approval"
            elif raw_status in ("Monitoring",):
                elapsed = (today_date - dec_date).days
                active_latencies.append(elapsed)
                latency_label = f"{elapsed}d (Active)"
                phase = "Under Review"
            elif raw_status == "Resolved" and not has_outcome:
                elapsed = (today_date - dec_date).days
                active_latencies.append(elapsed)
                latency_label = f"{elapsed}d (Active)"
                phase = "Outcome Pending"
            else:
                continue

            ctx_note = d.get("context_notes", "")
            if not ctx_note or str(ctx_note).strip().lower() in ("", "none", "null"):
                ctx_note = "No context note recorded."

            latency_rows.append({
                "Decision ID": dec_id,
                "Entry Date": dec_date_str,
                "Elapsed": latency_label,
                "Current Phase": phase,
                "Context Note": ctx_note,
            })

        summary = {}
        if total_tracked > 0:
            summary["total_tracked"] = total_tracked
            if resolved_latencies:
                summary["avg_resolved"] = f"{np.mean(resolved_latencies):.0f}d"
                summary["median_resolved"] = f"{np.median(resolved_latencies):.0f}d"
                summary["resolved_count"] = len(resolved_latencies)
            if active_latencies:
                summary["avg_active"] = f"{np.mean(active_latencies):.0f}d"
                summary["active_count"] = len(active_latencies)
                summary["max_active"] = f"{max(active_latencies)}d"

