        def get_file_timestamp(filepath):
            """Get file modification time in human-readable format."""
            from pathlib import Path
            import os
            try:
                p = Path(filepath)
                if p.exists():
                    mtime = os.path.getmtime(p)
                    from datetime import datetime
                    dt = datetime.fromtimestamp(mtime)
                    return dt.strftime("%Y-%m-%d %H:%M ET")
                return "Unavailable"
            except:
                return "Unavailable"
        
        def get_csv_asof_date(filepath):
            """Get asof date from CSV if available."""
            try:
                df = pd.read_csv(filepath)
                if "asof" in df.columns:
                    return df["asof"].iloc[0] if len(df) > 0 else "Unavailable"
                return get_file_timestamp(filepath)
            except:
                return get_file_timestamp(filepath)
        
