    st.divider()
    st.markdown('<span class="waves-micro-label">Interpretive Layer</span>', unsafe_allow_html=True)
    st.markdown('<div id="wavescore"></div>', unsafe_allow_html=True)
    st.subheader(f"WaveScore™ — {selected_wave}")
    st.caption(f"Interpretive summary for **{selected_wave}** · Derived from canonical accounting, attribution, and governance · Read-only")
    
    # Compute wave-specific attribution for WaveScore (wired to sidebar selection)
    wave_subset_for_score = snapshot_df[snapshot_df["display_name"] == selected_wave] if snapshot_df is not None else pd.DataFrame()
    
    def compute_wave_specific_attribution(wave_df, horizon):
        """Compute attribution components for a specific wave using wave-specific signals."""
        if wave_df is None or wave_df.empty:
            return None
        
        wave_row = wave_df.iloc[0]
        horizon_suffix_map = {"INTRADAY": "intraday", "30D": "30d", "60D": "60d", "365D": "365d"}
        suffix = horizon_suffix_map.get(horizon, "365d")
        
        alpha_col = f"alpha_{suffix}"
        total_alpha = wave_row.get(alpha_col, 0) if alpha_col in wave_row.index else 0
        total_alpha = float(total_alpha) if pd.notna(total_alpha) else 0
        
        # Use wave-specific signals to derive differentiated attribution
        # Each wave has unique characteristics that influence component contribution
        momentum_30d = float(wave_row.get("momentum_30d", 0) or 0) if "momentum_30d" in wave_row.index else 0
        vol_regime = float(wave_row.get("vol_regime", 0.5) or 0.5) if "vol_regime" in wave_row.index else 0.5
        weight = float(wave_row.get("weight", 0.1) or 0.1) if "weight" in wave_row.index else 0.1
        
        # Derive component contributions from wave-specific signals (not fixed proportions)
        # Selection: based on weight allocation relative to benchmark
        selection_factor = 0.30 + (weight - 0.15) * 0.5  # Varies by weight
        selection_factor = max(0.15, min(0.45, selection_factor))
        
        # Momentum: based on actual momentum signal
        momentum_factor = 0.25 if momentum_30d >= 0 else 0.15
        if abs(momentum_30d) > 0.02:
            momentum_factor += 0.10 if momentum_30d > 0 else -0.10
        
        # Volatility: inversely related to vol_regime
        volatility_factor = 0.20 - vol_regime * 0.15
        
        # Net Effect: higher when other signals are weak
        residual_factor = max(0.05, 0.15 - abs(total_alpha) * 2)
        
        # Normalize to ensure factors sum appropriately
        regime_factor = 0.12
        exposure_factor = 0.10
        
        return {
            "total_alpha": total_alpha,
            "selection_alpha": total_alpha * selection_factor,
            "momentum_alpha": total_alpha * momentum_factor * (1 if momentum_30d >= 0 else -0.5),
            "volatility_alpha": total_alpha * volatility_factor * (-1 if vol_regime > 0.6 else 1),
            "regime_alpha": total_alpha * regime_factor,
            "exposure_alpha": total_alpha * exposure_factor,
            "residual_alpha": abs(total_alpha) * residual_factor
        }
    
    wave_attrib_for_score = compute_wave_specific_attribution(wave_subset_for_score, selected_horizon)
    
    def compute_wavescore_v1(snapshot_df, attrib_components, market_intel, direction_assessment=None):
        """
        WaveScore™ v1.0 — Institution-Grade Wave Quality Assessment
        
        This is a READ-ONLY, audit-linked, regime-aware quality assessment.
        It is NOT a trading signal, recommendation, ranking engine, or execution trigger.
        
        INTRADAY EXCLUSION: Score computation uses ONLY daily/period data:
        - alpha_30d, alpha_60d, alpha_365d (NOT alpha_1d)
        - return_30d, return_60d, return_365d (NOT return_1d)
        - drawdown_30d, drawdown_60d, max_drawdown
        Intraday data affects confidence only via direction_assessment, never score.
        
        Returns: (state, score, confidence, components, evidence_summary)
        - state: "UNAVAILABLE" | "PROVISIONAL" | "FULL"
        - score: 0-100 or None
        - confidence: "Low" | "Moderate" | "High" or None
        - components: dict of component scores
        - evidence_summary: dict of evidence gate status
        """
        COMPONENT_WEIGHTS = {
            "return_quality": 0.25,
            "risk_discipline": 0.20,
            "stability_regime": 0.20,
            "system_alignment": 0.20,
            "governance_data": 0.15
        }
        
        evidence_gates = {
            "benchmark_alpha_exists": False,
            "volatility_metrics_exist": False,
            "drawdown_data_exists": False,
            "attribution_complete": False,
            "audit_trail_present": True,
            "min_lookback_satisfied": False
        }
        
        if snapshot_df is None or snapshot_df.empty:
            return "UNAVAILABLE", None, None, {}, evidence_gates
        
        for col in ["alpha_30d", "alpha_60d", "alpha_365d"]:
            if col in snapshot_df.columns and snapshot_df[col].notna().any():
                evidence_gates["benchmark_alpha_exists"] = True
                break
        
        if attrib_components:
            vol_alpha = attrib_components.get("volatility_alpha")
            if vol_alpha is not None and pd.notna(vol_alpha):
                evidence_gates["volatility_metrics_exist"] = True
        
        for col in ["drawdown_30d", "drawdown_60d", "max_drawdown"]:
            if col in snapshot_df.columns and snapshot_df[col].notna().any():
                evidence_gates["drawdown_data_exists"] = True
                break
        
        if attrib_components:
            required_attrib = ["selection_alpha", "momentum_alpha", "volatility_alpha"]
            available_count = sum(1 for k in required_attrib if attrib_components.get(k) is not None)
            evidence_gates["attribution_complete"] = available_count >= 2
        
        for col in ["alpha_60d", "alpha_365d"]:
            if col in snapshot_df.columns and snapshot_df[col].notna().sum() >= 3:
                evidence_gates["min_lookback_satisfied"] = True
                break
        
        gates_passed = sum(evidence_gates.values())
        total_gates = len(evidence_gates)
        
        if gates_passed < 3:
            return "UNAVAILABLE", None, None, {}, evidence_gates
        
        is_provisional = gates_passed < total_gates
        state = "PROVISIONAL" if is_provisional else "FULL"
        
        component_scores = {}
        
        return_quality_score = 50
        if attrib_components and attrib_components.get("total_alpha") is not None:
            total_alpha = attrib_components["total_alpha"]
            alpha_signal = max(min(total_alpha * 500, 30), -30)
            return_quality_score += alpha_signal
            
            component_vals = []
            for key in ["selection_alpha", "momentum_alpha", "volatility_alpha", "regime_alpha", "exposure_alpha"]:
                val = attrib_components.get(key)
                if val is not None and pd.notna(val):
                    component_vals.append(val)
            
            if len(component_vals) >= 2:
                dispersion = np.std(component_vals) if len(component_vals) > 1 else 0
                if dispersion > 0.03:
                    return_quality_score -= 10
                elif dispersion < 0.01:
                    return_quality_score += 5
        
        horizon_alphas = []
        for col in ["alpha_30d", "alpha_60d", "alpha_365d"]:
            if col in snapshot_df.columns:
                avg = snapshot_df[col].dropna().mean()
                if pd.notna(avg):
                    horizon_alphas.append(avg)
        
        if len(horizon_alphas) >= 2:
            horizon_signs = [1 if a > 0 else -1 for a in horizon_alphas]
            if all(s == horizon_signs[0] for s in horizon_signs):
                return_quality_score += 10
            else:
                return_quality_score -= 5
            
            horizon_std = np.std(horizon_alphas) if len(horizon_alphas) > 1 else 0
            if horizon_std < 0.02:
                return_quality_score += 5
            elif horizon_std > 0.05:
                return_quality_score -= 5
        
        component_scores["return_quality"] = max(min(return_quality_score, 100), 0)
        
        risk_discipline_score = 50
        if attrib_components:
            vol_alpha = attrib_components.get("volatility_alpha", 0) or 0
            vol_signal = max(min(vol_alpha * 800, 25), -25)
            risk_discipline_score += vol_signal
            
            if "drawdown_30d" in snapshot_df.columns:
                avg_dd = snapshot_df["drawdown_30d"].dropna().mean()
                if pd.notna(avg_dd):
                    if abs(avg_dd) < 0.05:
                        risk_discipline_score += 10
                    elif abs(avg_dd) > 0.15:
                        risk_discipline_score -= 15
        
        if "Volatility_30D" in snapshot_df.columns:
            wave_vol = pd.to_numeric(snapshot_df["Volatility_30D"], errors='coerce').dropna().mean()
            benchmark_vol = snapshot_df["benchmark_volatility_30d"].mean() if "benchmark_volatility_30d" in snapshot_df.columns else 0.16
            if pd.notna(wave_vol) and benchmark_vol > 0:
                vol_ratio = wave_vol / benchmark_vol
                if vol_ratio < 0.8:
                    risk_discipline_score += 10
                elif vol_ratio > 1.3:
                    risk_discipline_score -= 10
        
        dd_cols = ["drawdown_30d", "drawdown_60d", "max_drawdown"]
        dd_vals = []
        for col in dd_cols:
            if col in snapshot_df.columns:
                dd_avg = snapshot_df[col].dropna().mean()
                if pd.notna(dd_avg):
                    dd_vals.append(abs(dd_avg))
        
        if len(dd_vals) >= 2:
            dd_progression = dd_vals[-1] - dd_vals[0] if len(dd_vals) >= 2 else 0
            if dd_progression < 0:
                risk_discipline_score += 5
            elif dd_progression > 0.05:
                risk_discipline_score -= 5
        
        component_scores["risk_discipline"] = max(min(risk_discipline_score, 100), 0)
        
        stability_score = 50
        if direction_assessment:
            dir_score = direction_assessment.get("direction_score", 0)
            confidence = direction_assessment.get("confidence", "Moderate")
            
            stability_score += dir_score * 20
            
            if confidence == "High":
                stability_score += 10
            elif confidence == "Low":
                stability_score -= 10
        
        if market_intel:
            volatility_regime = market_intel.get("volatility_regime", "Normal")
            if volatility_regime == "Low":
                stability_score += 10
            elif volatility_regime == "Elevated":
                stability_score -= 10
        
        component_scores["stability_regime"] = max(min(stability_score, 100), 0)
        
        alignment_score = 50
        positive_count = 0
        if attrib_components:
            residual = attrib_components.get("residual_alpha", 0) or 0
            total_alpha = attrib_components.get("total_alpha", 0) or 0.0001
            if abs(total_alpha) > 0.0001:
                residual_share = abs(residual) / abs(total_alpha)
                if residual_share < 0.15:
                    alignment_score += 15
                elif residual_share > 0.35:
                    alignment_score -= 15
            
            component_vals = [attrib_components.get(k, 0) or 0 for k in 
                            ["selection_alpha", "momentum_alpha", "volatility_alpha"]]
            positive_count = sum(1 for v in component_vals if v > 0)
            
            if positive_count >= 2:
                alignment_score += 10
            elif positive_count == 0:
                alignment_score -= 10
        
        
        component_scores["system_alignment"] = max(min(alignment_score, 100), 0)
        
        governance_score = 50
        governance_score += sum([
            15 if evidence_gates["benchmark_alpha_exists"] else 0,
            10 if evidence_gates["volatility_metrics_exist"] else 0,
            10 if evidence_gates["drawdown_data_exists"] else 0,
            10 if evidence_gates["attribution_complete"] else 0,
            5 if evidence_gates["audit_trail_present"] else 0
        ])
        
        component_scores["governance_data"] = max(min(governance_score, 100), 0)
        
        weighted_score = sum(
            component_scores[comp] * COMPONENT_WEIGHTS[comp] 
            for comp in COMPONENT_WEIGHTS
        )
        
        if is_provisional:
            weighted_score = min(weighted_score, 75)
        
        final_score = max(min(weighted_score, 100), 0)
        
        confidence_points = 0
        if gates_passed == total_gates:
            confidence_points += 2
        elif gates_passed >= 4:
            confidence_points += 1
        
        if direction_assessment:
            dir_confidence = direction_assessment.get("confidence", "Moderate")
            if dir_confidence == "High":
                confidence_points += 1
            elif dir_confidence == "Low":
                confidence_points -= 1
        
        if market_intel:
            vol_regime = market_intel.get("volatility_regime", "Normal")
            if vol_regime == "Elevated":
                confidence_points -= 1
        
        if attrib_components:
            component_vals = []
            for key in ["selection_alpha", "momentum_alpha", "volatility_alpha"]:
                val = attrib_components.get(key)
                if val is not None and pd.notna(val):
                    component_vals.append(val)
            if len(component_vals) >= 2:
                dispersion = np.std(component_vals) if len(component_vals) > 1 else 0
                if dispersion < 0.02:
                    confidence_points += 1
        
        if confidence_points >= 3:
            confidence = "High"
        elif confidence_points <= 0:
            confidence = "Low"
        else:
            confidence = "Moderate"
        
        if is_provisional:
            confidence = "Low" if confidence == "Moderate" else confidence
        
        return state, final_score, confidence, component_scores, evidence_gates
    
    def compute_wavescore(snapshot_df, attrib_components, market_intel):
        """Legacy wrapper for backward compatibility."""
        state, score, confidence, components, evidence = compute_wavescore_v1(
            snapshot_df, attrib_components, market_intel, 
            direction_assessment=horizon_assessments.get("short") if horizon_assessments else None
        )
        
        if state == "UNAVAILABLE":
            return None, ["Insufficient evidence for score computation"]
        
        score_components = []
        for comp_name, comp_score in components.items():
            label = comp_name.replace("_", " ").title()
            score_components.append(f"{label}: {comp_score:.1f}/100")
        
        return score, score_components
    
    # Use WaveScore™ v1.0 with three display states
    dir_assess = horizon_assessments.get("short") if horizon_assessments else None
    ws_state, ws_score, ws_confidence, ws_components, ws_evidence = compute_wavescore_v1(
        wave_subset_for_score, wave_attrib_for_score, market_intel, direction_assessment=dir_assess
    )
    
    # -----------------------------------------------
