            review_areas = [r for r in heatmap_data if r.get("Status") == "Review Recommended"] if heatmap_data else []
            monitoring_areas = [r for r in heatmap_data if r.get("Status") == "Monitoring"] if heatmap_data else []
            stable_areas = [r for r in heatmap_data if r.get("Status") == "Stable"] if heatmap_data else []
