                raw["Market Beta"] = beta_val if beta_val > 0 else 1

                align_map = {"Aligned": 3, "Mixed": 2, "Diverging": 1, "Data Insufficient": 1}
                raw["Regime Alignment"] = align_map.get(alignment, 1) * 2

                total_raw = sum(raw.values())
                residual_pct = max(5, 100 - sum(v / total_raw * 95 for v in raw.values()))
                normalized = {}
                non_residual_total = sum(raw.values())
                for k, v in raw.items():
                    normalized[k] = round(v / non_residual_total * (100 - residual_pct), 1)
                normalized["Residual"] = round(100 - sum(normalized.values()), 1)

                directions = {}
                directions["Momentum"] = "Positive" if (ret is not None and ret > 0.005) else "Detracting" if (ret is not None and ret < -0.005) else "Neutral"
                directions["Volatility"] = "Detracting" if (vol is not None and vol > 0.30) else "Positive" if (vol is not None and vol < 0.15) else "Neutral"
                directions["Market Beta"] = "Positive" if (rs is not None and rs > 0.01) else "Detracting" if (rs is not None and rs < -0.01) else "Neutral"
                directions["Regime Alignment"] = "Positive" if alignment == "Aligned" else "Detracting" if alignment == "Diverging" else "Neutral"
                directions["Residual"] = "Neutral"

