    _sle_engagement_score = min(100.0, _sle_engagement_score)

    _sle_implemented = sum(1 for d in _sle_decisions if d.get("status") in ["Recorded", "Completed"])
    _sle_implementation_score = (_sle_implemented / _sle_total_decisions * 100) if _sle_total_decisions > 0 else 50.0

    _sle_latency_days_list = []
    from datetime import datetime as _sle_dt_cls
    _sle_sorted_decisions = sorted(_sle_decisions, key=lambda x: x.get("date", ""))
    for _sle_idx, _sle_d in enumerate(_sle_sorted_decisions):
        _sle_d_date = _sle_d.get("date", "")
        if not _sle_d_date:
            continue
        try:
            _sle_d_parsed = _sle_dt_cls.strptime(_sle_d_date, "%Y-%m-%d")
            _sle_linked = _sle_d.get("linked_decision_id") or _sle_d.get("linked_signal_id")
            if _sle_linked:
                _sle_linked_dec = next((dd for dd in _sle_decisions if dd.get("id") == _sle_linked), None)
                if _sle_linked_dec and _sle_linked_dec.get("date"):
                    _sle_linked_dt = _sle_dt_cls.strptime(_sle_linked_dec["date"], "%Y-%m-%d")
                    _sle_latency_days_list.append(max(0, (_sle_d_parsed - _sle_linked_dt).days))
                    continue
            if _sle_idx > 0 and _sle_sorted_decisions[_sle_idx - 1].get("date"):
                _sle_prev_dt = _sle_dt_cls.strptime(_sle_sorted_decisions[_sle_idx - 1]["date"], "%Y-%m-%d")
                _sle_latency_days_list.append(max(0, (_sle_d_parsed - _sle_prev_dt).days))
            else:
                _sle_latency_days_list.append(2)
        except Exception:
            pass
    _sle_avg_latency = sum(_sle_latency_days_list) / len(_sle_latency_days_list) if _sle_latency_days_list else 5.0

    if _sle_avg_latency <= 2:
        _sle_latency_score = 100.0
    elif _sle_avg_latency <= 5:
        _sle_latency_score = 80.0
    elif _sle_avg_latency <= 10:
        _sle_latency_score = 60.0
    else:
        _sle_latency_score = 40.0

    _sle_efficiency_index = max(0.0, min(100.0,
        (_sle_engagement_score * 0.40) +
        (_sle_implementation_score * 0.30) +
        (_sle_latency_score * 0.30)
    ))

    if _sle_efficiency_index >= 90:
        _sle_eff_grade = "A"
    elif _sle_efficiency_index >= 80:
        _sle_eff_grade = "B"
    elif _sle_efficiency_index >= 65:
        _sle_eff_grade = "C"
    elif _sle_efficiency_index >= 50:
        _sle_eff_grade = "D"
    else:
        _sle_eff_grade = "Early-stage"

    _sle_learn_color = "#48BB78" if _sle_learn_grade == "A" else "#5C6BC0" if _sle_learn_grade == "B" else "#FFA726" if _sle_learn_grade in ["C", "D"] else "#8A9BB5"
    _sle_eff_color = "#48BB78" if _sle_eff_grade == "A" else "#5C6BC0" if _sle_eff_grade == "B" else "#FFA726" if _sle_eff_grade in ["C", "D"] else "#8A9BB5"

    _sle_grade_cols = st.columns(2)
