        stage_counts = dlm.compute_stage_counts(all_decisions_dlm, snapshot_df, attrib_df, dlm_scope, dlm_selected_wave)

        stage_labels = ["1. Signal\nContext", "2. Issue /\nOpportunity", "3. Decision\nFormation", "4. Approval &\nGovernance", "5. Implementation\n& Monitoring", "6. Outcome\nObservation", "7. Learning &\nAdaptation", "8. Finalization\n& Handoff"]
        status_colors = {"Active": "#3A6FF7", "Quiet": "#4B5563", "Insufficient Data": "#6B7280"}

        strip_html = '<div style="display: flex; gap: 6px; overflow-x: auto; padding: 8px 0; -webkit-overflow-scrolling: touch;">'
