    st.markdown('<span class="waves-micro-label">Institutional Governance</span>', unsafe_allow_html=True)
    st.markdown('<div id="decision-lifecycle"></div><div id="decision-timeline"></div>', unsafe_allow_html=True)
    st.subheader("Decision Lifecycle")
