    # Build outcome data from existing sources
    def get_decision_outcomes():
        """Gather decision outcome data from existing sources."""
        import json
        from datetime import datetime, timedelta

        outcomes = {
            "metrics": {
                "total": 0,
                "aligned": 0,
                "mixed": 0,
                "external": 0,
                "insufficient": 0
            },
            "decisions": [],
            "summary": "No finalized decisions within the current review window."
        }

        ctx_notes_map = {}
        try:
            dl_path = Path("data/decision_log.json")
            if dl_path.exists():
                dl_data = json.loads(dl_path.read_text())
                for dl_entry in dl_data:
                    did = dl_entry.get("id", "")
                    cn = dl_entry.get("context_notes", "")
                    if did and cn and str(cn).strip().lower() not in ("", "none", "null"):
                        ctx_notes_map[did] = cn
        except Exception:
            pass

        # Check for decision history
        decision_history_path = Path("data/decision_history.json")
        if not decision_history_path.exists():
            return outcomes

        try:
            decisions = json.loads(decision_history_path.read_text())
            if not decisions or len(decisions) == 0:
                return outcomes

            today = datetime.now()
            ninety_days_ago = today - timedelta(days=90)

            # Filter to last 90 days
            recent_decisions = []
            for d in decisions:
                try:
                    d_date = datetime.fromisoformat(d.get("timestamp", "2000-01-01")[:10])
                    if d_date >= ninety_days_ago:
                        recent_decisions.append(d)
                except:
                    continue

            if not recent_decisions:
                return outcomes

            outcomes["metrics"]["total"] = len(recent_decisions)

            # Classify each decision
            for d in recent_decisions[-5:]:  # Show last 5
                dec_id = d.get("id", "—")
                decision_entry = {
                    "id": dec_id,
                    "type": d.get("type", "—"),
                    "actor": d.get("actor", "—"),
                    "timestamp": d.get("timestamp", "—")[:10] if d.get("timestamp") else "—",
                    "outcome_30d": "Pending",
                    "outcome_90d": "Pending",
                    "outcome_365d": "Pending",
                    "learning": "Insufficient Data",
                    "context_note": ctx_notes_map.get(dec_id, d.get("context_notes", "No context note recorded.")) or "No context note recorded."
                }

                # Try to derive outcomes from snapshot data
                if snapshot_df is not None and not snapshot_df.empty:
                    if "return_30d" in snapshot_df.columns:
                        avg_30d = snapshot_df["return_30d"].mean()
                        if not pd.isna(avg_30d):
                            decision_entry["outcome_30d"] = f"{avg_30d*100:+.1f}%"
                    if "return_90d" in snapshot_df.columns:
                        avg_90d = snapshot_df["return_90d"].mean()
                        if not pd.isna(avg_90d):
                            decision_entry["outcome_90d"] = f"{avg_90d*100:+.1f}%"
                    if "return_365d" in snapshot_df.columns:
                        avg_365d = snapshot_df["return_365d"].mean()
                        if not pd.isna(avg_365d):
                            decision_entry["outcome_365d"] = f"{avg_365d*100:+.1f}%"

                # Derive learning signal from stability
                if attrib_df is not None and not attrib_df.empty:
                    numeric_cols = attrib_df.select_dtypes(include=[np.number]).columns
                    if len(numeric_cols) > 0:
                        attrib_std = attrib_df[numeric_cols].std().mean()
                        if attrib_std > 0.05:
                            decision_entry["learning"] = "Regime-Sensitive"
                            outcomes["metrics"]["external"] += 1
                        elif attrib_std > 0.03:
                            decision_entry["learning"] = "Mixed"
                            outcomes["metrics"]["mixed"] += 1
                        else:
                            decision_entry["learning"] = "Stable"
                            outcomes["metrics"]["aligned"] += 1
                    else:
                        outcomes["metrics"]["insufficient"] += 1
                else:
                    outcomes["metrics"]["insufficient"] += 1

                outcomes["decisions"].append(decision_entry)

            # Generate summary sentence
            if outcomes["metrics"]["aligned"] > outcomes["metrics"]["mixed"] + outcomes["metrics"]["external"]:
                outcomes["summary"] = "Recent decisions show broadly stable outcomes across observed horizons."
            elif outcomes["metrics"]["external"] > 0:
                outcomes["summary"] = "Short-term outcomes were regime-sensitive, with stabilization over longer horizons."
            elif outcomes["metrics"]["mixed"] > 0:
                outcomes["summary"] = "Decision outcomes remain mixed across contexts and horizons."
            else:
                outcomes["summary"] = "Outcome visibility remains limited due to short decision history."

        except:
            pass

        return outcomes

