        if not wr_waves and wr_snapshot is not None and not wr_snapshot.empty:
            wr_waves = wr_snapshot[wr_name_col].dropna().unique().tolist()

        def classify_wave_health(wave_name, snap_df, attr_df, name_col):
            row = snap_df[snap_df[name_col] == wave_name].iloc[0] if len(snap_df[snap_df[name_col] == wave_name]) > 0 else None
            if row is None:
                return "Insufficient Data", {}

            a30 = float(row.get("alpha_30d", 0) or 0)
            a60 = float(row.get("alpha_60d", 0) or 0)
            a365 = float(row.get("alpha_365d", 0) or 0)
            bvol = float(row.get("benchmark_volatility_30d", 0) or 0)
            dd = float(row.get("drawdown_30d", 0) or 0)
            r30 = float(row.get("return_30d", 0) or 0)
            br30 = float(row.get("benchmark_return_30d", 0) or 0)

            regime_aligned = True
            if bvol > 0.20 and a30 < -0.01:
                regime_aligned = False
            if bvol < 0.10 and a30 < 0:
                regime_aligned = False

            attr_row = attr_df[attr_df["wave"] == wave_name] if attr_df is not None and "wave" in attr_df.columns else pd.DataFrame()
            attr_30 = attr_row[attr_row["horizon"] == 30].iloc[0] if len(attr_row[attr_row["horizon"] == 30]) > 0 else None

            pos_driver = "—"
            neg_driver = "—"
            if attr_30 is not None:
                components = {"Selection": float(attr_30.get("selection_alpha", 0) or 0),
                              "Momentum": float(attr_30.get("momentum_alpha", 0) or 0),
                              "Volatility": float(attr_30.get("volatility_alpha", 0) or 0),
                              "Regime": float(attr_30.get("regime_alpha", 0) or 0),
                              "Allocation": float(attr_30.get("exposure_alpha", 0) or 0)}
                sorted_comp = sorted(components.items(), key=lambda x: x[1], reverse=True)
                pos_driver = sorted_comp[0][0] if sorted_comp[0][1] > 0 else "None"
                neg_driver = sorted_comp[-1][0] if sorted_comp[-1][1] < 0 else "None"

            neg_count = sum(1 for a in [a30, a60, a365] if a < -0.005)

            if neg_count >= 2 or (not regime_aligned and a30 < -0.01):
                status = "Review Recommended"
            elif neg_count == 1 or abs(a30) < 0.005 or not regime_aligned:
                status = "Monitoring"
            else:
                status = "Stable"

            if a30 > 0 and (r30 - br30) > -0.01:
                regime_label = "Aligned"
            elif abs(a30) < 0.005:
                regime_label = "Neutral"
            else:
                regime_label = "Misaligned"

            details = {
                "alpha_30d": a30, "alpha_60d": a60, "alpha_365d": a365,
                "regime_alignment": regime_label,
                "pos_driver": pos_driver, "neg_driver": neg_driver,
                "benchmark_vol": bvol, "drawdown": dd,
            }
            return status, details

